class TutorReply{final String text;final int xp;const TutorReply(this.text,{this.xp=5});}
abstract class AiTutorService{Future<TutorReply>reply({required String topic,required String level,required String userText});}
class DemoAiTutorService implements AiTutorService{@override Future<TutorReply>reply({required String topic,required String level,required String userText})async{await Future<void>.delayed(const Duration(milliseconds:650));final s=userText.trim().toLowerCase();if(s.contains('менің аты'))return const TutorReply('Керемет! «Менің атым ...» — дұрыс үлгі. Енді қай қалада тұратыныңды айт.',xp:10);if(s.contains('сәлем')||s.contains('салам'))return const TutorReply('Сәлем! 👋 Өзіңді қазақша таныстыршы.',xp:8);if(s.length<5)return const TutorReply('Жақсы бастама. Толық сөйлеммен жауап беріп көрші.',xp:3);return TutorReply('Жақсы жауап! 👏 '+topic+' тақырыбын жалғастырайық. Осы ойды қазақша тағы бір сөйлеммен айт.',xp:7);}}